pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, uint256 v, address recipient) public {
        Reverter bad = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = recipient == address(0) ? address(bad) : recipient;

        bool ok = true;
        try c.transfer(from, address(bad), tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || bad.called());
    }
}

contract Reverter {
    bool public called;

    fallback() external payable {
        called = true;
        revert();
    }
}
